"""Portable before/after review and explicit implemented/pending catalog report."""
import argparse
import json
from pathlib import Path
from PIL import Image
from catalog import refresh_status, load_frame
from pipeline import process, save_png, atomic_json

def build(root, project):
    root=Path(root);catalog=refresh_status(root);records=[]
    report=['# Catálogo do player — estado da produção','',
            '44 ações planejadas. Existem 28 sequências principais por personagem no recurso ativo. Não há sprites próprios das outras 37 ações nesses recursos.',
            '','## Preservação','',
            'Idle: 14 entradas por direção, com repetições de retorno e durações de 1,5 preservadas; 6 FPS. Walk: oito entradas por direção; 9 FPS frente/costas e 12 FPS nas laterais. A meta inicial de oito quadros não substitui o ciclo aprovado.',
            '','Nenhum sprite ativo foi substituído. Os candidatos exportados não são aprovação artística. P0 não passa por img2img; limpeza não altera a máscara do corpo, a ordem dos quadros nem o tempo. Fragmentos pequenos acima da cabeça e pixels isolados de P0 são removidos com registro de coordenadas.',
            '','## Inventário','',
            '| Ação | Prioridade | Feminino: sequências na origem | Masculino: sequências na origem | Estado dos novos sprites |','|---|---:|---:|---:|---|']
    for action in catalog['actions']:
        counts=[sum(bool(v['source_frame_count']) for v in catalog['characters'][c].values() if v['action']==action['id']) for c in ('feminino','masculino')]
        report.append(f"| {action['id']} | P{action['priority']} | {counts[0]} | {counts[1]} | {'Referências disponíveis; revisão necessária' if counts[0] else 'Faltam poses desenhadas e validadas'} |")
    for character,rows in catalog['characters'].items():
        for name,row in rows.items():
            for mode,state in row['candidates'].items():
                if not state['export_path']:continue
                folder=root/state['export_path'];meta=json.loads((folder/'metadata.json').read_text(encoding='utf8'))
                before=root/character/name/'before';before.mkdir(parents=True,exist_ok=True)
                for i,frame in enumerate(row['pose_references']):save_png(process(load_frame(project,frame),colors=256),before/f'{i:03}.png')
                records.append(dict(character=character,name=name,mode=mode,fps=meta['fps'],durations=meta['durations'],loop=meta['loop'],before=[str((before/f'{i:03}.png').relative_to(root)).replace('\\','/') for i in range(meta['frame_count'])],after=[str((folder/f'frames/{i:03}.png').relative_to(root)).replace('\\','/') for i in range(meta['frame_count'])],sheet=str((folder/'sheet.png').relative_to(root)).replace('\\','/'),preview=str((folder/'preview.png').relative_to(root)).replace('\\','/'),metadata=str((folder/'metadata.json').relative_to(root)).replace('\\','/'),validation=meta['validation']))
    atomic_json(root/'review_data.json',records)
    report += ['','## Qualidade e limitações','',
               'A limpeza reaproveita process(), shared_palette(), constrain_mask(), protect_contour() e export(). A etapa adicional recolore apenas pontos internos isolados de baixo contraste cercados por sete vizinhos da mesma cor; não apaga a silhueta do corpo nem detalhes escuros contrastantes. A regra de fragmentos é restrita a P0 e não é aplicada a partículas das ferramentas.',
               '','Persistem defeitos das referências: recortes atravessando pés/ferramentas, fragmentos de linhas vizinhas, variação de apoio e detalhes de textura. Partículas de água precisam de máscara própria para separá-las dos fragmentos indevidos. Não se remove todo componente desconectado indiscriminadamente.',
               '','Os arquivos de poses das 37 ações ausentes não foram fabricados com caminhada reutilizada. Os eventos são planos não validados até definir seus quadros e sockets nas poses reais. hold_slime ainda precisa de variantes parada/caminhando, com mãos e slime sincronizados.',
               '','## Integração','',
               'O sequenciador opt-in em godot/action_sequencer.gd oferece bloqueio, cancelamento, retorno da fase anterior e sinais de sincronização. Foi testado em projeto isolado; não está ligado ao controlador ativo nem emite seus impactos de ferramenta. Somente definições de eventos validadas são aceitas. Cada futura ação deve ligar sinais ao alvo correspondente e especificar pontos de mão/ferramenta por quadro.',
               '','## Execução','',
               'Use production.py --output DIRETORIO --character feminino --actions idle walk --limit 2 para processamento local retomável. Para img2img, selecione uma ação P1+ e direção, acrescente --sd --pose-review ARQUIVO. O lote exige revisão completa das poses vinculada aos hashes das fontes e usa apenas uma imagem por chamada. O limite padrão é dois quadros. Repita o comando até exportar a sequência; não há geração simultânea.',
               '','As referências desta revisão foram congeladas após detectar alteração externa do recurso. Um hash diferente bloqueia retomada. Inspecione a origem atual e use uma nova saída para uma revisão posterior. Não apague um arquivo production.lock enquanto o processo correspondente estiver ativo.',
               '','Os testes de importação não equivalem a aprovação de anatomia, fluidez ou qualidade profissional.']
    (root/'RELATORIO.md').write_text('\n'.join(report),encoding='utf8')
    page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo do player</title><style>*{box-sizing:border-box}body{font:16px system-ui;color:#edf2f3;background:#14212a;max-width:1180px;margin:auto;padding:28px}h1{margin-bottom:8px}p{color:#bccbd2;line-height:1.6}a{color:#8de2c8}select,button{padding:10px;border:1px solid #526c7b;border-radius:6px;background:#223541;color:white;margin:5px}main{display:flex;gap:20px;flex-wrap:wrap}figure{margin:0;background:#243541;padding:16px;border-radius:12px}canvas{width:320px;height:320px;max-width:100%;image-rendering:pixelated;background:repeating-conic-gradient(#33444d 0% 25%,#2c3c45 0% 50%) 50%/16px 16px}figcaption{margin:8px 0}input{width:min(650px,90%)}#status{padding:16px;background:#29322e;border-left:3px solid #d2b869}li{margin:6px 0}</style><h1>Catálogo de animações do player</h1><p>44 ações cadastradas. Compare referências existentes e candidatos. As animações aprovadas mantêm poses, ordem e tempos; nenhum sprite ativo foi substituído.</p><p><a href="catalog.json">Catálogo completo e estados</a> · <a href="RELATORIO.md">Implementadas, pendentes e limitações</a> · <a href="palettes/feminino.json">Paleta feminina</a> · <a href="palettes/masculino.json">Paleta masculina</a></p><label>Personagem <select id="character"><option value="feminino">Feminino</option><option value="masculino">Masculino</option></select></label><label>Sequência <select id="sequence"></select></label><button id="play">Pausar</button><button id="restart">Reiniciar</button><p id="timing"></p><main><figure><canvas id="before" width="64" height="64"></canvas><figcaption>Referência — 64×64, até 256 cores</figcaption></figure><figure><canvas id="after" width="64" height="64"></canvas><figcaption id="caption">Paleta compartilhada + limpeza</figcaption></figure></main><p><input id="frame" type="range" min="0" value="0"><span id="position"></span></p><p id="links"></p><section id="status"></section><script>
const records=DATA;let selected,images,index=0,playing=true,last=performance.now();const $=id=>document.getElementById(id);function image(src){const im=new Image;im.onload=draw;im.src=src;return im}function draw(){if(!images)return;for(const side of ['before','after']){const cv=$(side),ctx=cv.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,64,64);const im=images[side][index];if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}$('frame').value=index;$('position').textContent=`${index+1} / ${selected.durations.length}`}function choose(){selected=records[+$('sequence').value];index=0;last=performance.now();images={before:selected.before.map(image),after:selected.after.map(image)};$('frame').max=selected.durations.length-1;$('timing').textContent=`${selected.fps} FPS · durações originais preservadas · ${selected.loop?'ciclo':'ação sem loop'}`;$('caption').textContent=selected.mode==='sd'?'Img2img + paleta e contorno protegido':'Paleta compartilhada + limpeza';$('links').replaceChildren();for(const [label,url] of [['Sprite sheet',selected.sheet],['APNG',selected.preview],['Metadados',selected.metadata]]){const a=document.createElement('a');a.textContent=label;a.href=url;$('links').append(a,document.createTextNode(' · '))}$('status').replaceChildren();const title=document.createElement('strong');title.textContent=selected.validation.structural_ok?'Estrutura válida — revisão artística pendente':'Há problemas herdados da referência — não substituir sprites';$('status').append(title);const ul=document.createElement('ul');for(const issue of selected.validation.issues){const li=document.createElement('li');li.textContent=issue;ul.append(li)}$('status').append(ul);draw()}function populate(){$('sequence').replaceChildren();records.forEach((r,i)=>{if(r.character===$('character').value){const o=document.createElement('option');o.value=i;o.textContent=r.name+' / '+(r.mode==='sd'?'ensaio SD':'limpeza');$('sequence').append(o)}});choose()}$('character').onchange=populate;$('sequence').onchange=choose;$('play').onclick=()=>{playing=!playing;last=performance.now();$('play').textContent=playing?'Pausar':'Reproduzir'};$('restart').onclick=()=>{index=0;last=performance.now();draw()};$('frame').oninput=e=>{playing=false;$('play').textContent='Reproduzir';index=+e.target.value;draw()};function tick(t){if(playing&&t-last>=1000*selected.durations[index]/selected.fps){last=t;if(index<selected.durations.length-1)index++;else if(selected.loop)index=0;else {playing=false;$('play').textContent='Reproduzir'}draw()}requestAnimationFrame(tick)}populate();requestAnimationFrame(tick);
</script></html>'''.replace('DATA',json.dumps(records,ensure_ascii=False).replace('</','<\\/'))
    (root/'REVISAR_CATALOGO.html').write_text(page,encoding='utf8')
    return records

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--project',default=r'C:\FarmSlime');a=p.parse_args();print('Review sequences:',len(build(a.output,a.project)))
